101e7226-60dd-4b8b-85ea-4f140ffd3584	1	dc4a8863-d7f6-47f5-88c1-57eb9eb399d3	Cases by ASA Status - Distinct Colors	<style>\n  #chart { width: 100%; height: 300px; }\n  .bar-asa1 { fill: #4CAF50; }\n  .bar-asa2 { fill: #2196F3; }\n  .bar-asa3 { fill: #FF9800; }\n  .bar-asa4 { fill: #F44336; }\n  .bar-asae { fill: #9C27B0; }\n</style>\n<div id="chart"></div>\n<script>\n  const data = FLORA.series("asa_data", {x: "ASA", y: "Cases"});\n  const chartDiv = document.getElementById("chart");\n  \n  // Clear existing content\n  chartDiv.innerHTML = '';\n  \n  // Create SVG container\n  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");\n  svg.setAttribute("width", "100%");\n  svg.setAttribute("height", "100%");\n  svg.setAttribute("viewBox", "0 0 400 300");\n  chartDiv.appendChild(svg);\n  \n  // Define colors for each ASA category\n  const colors = {\n    "ASA 1": "#4CAF50",\n    "ASA 2": "#2196F3",\n    "ASA 3": "#FF9800",\n    "ASA 4": "#F44336",\n    "ASA 1E": "#9C27B0",\n    "ASA 2E": "#9C27B0",\n    "ASA 3E": "#9C27B0"\n  };\n  \n  // Calculate dimensions\n  const margin = {top: 20, right: 20, bottom: 40, left: 50};\n  const width = 400 - margin.left - margin.right;\n  const height = 300 - margin.top - margin.bottom;\n  \n  // Create chart area\n  const g = document.createElementNS("http://www.w3.org/2000/svg", "g");\n  g.setAttribute("transform", `translate(${margin.left},${margin.top})`);\n  svg.appendChild(g);\n  \n  // Scales\n  const xScale = (i) => i * (width / data.labels.length);\n  const yScale = (v) => height - (v / Math.max(...data.series[0].values)) * height;\n  \n  // Draw bars\n  data.labels.forEach((label, i) => {\n    const value = data.series[0].values[i];\n    const barHeight = yScale(value);\n    \n    const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");\n    rect.setAttribute("x", xScale(i));\n    rect.setAttribute("y", height - barHeight);\n    rect.setAttribute("width", width / data.labels.length - 10);\n    rect.setAttribute("height", barHeight);\n    rect.setAttribute("fill", colors[label] || "#666");\n    g.appendChild(rect);\n    \n    // Add value label on top of bar\n    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");\n    text.setAttribute("x", xScale(i) + (width / data.labels.length) / 2);\n    text.setAttribute("y", height - barHeight - 5);\n    text.setAttribute("text-anchor", "middle");\n    text.setAttribute("fill", "#333");\n    text.textContent = value;\n    g.appendChild(text);\n    \n    // Add category label below x-axis\n    const labelEl = document.createElementNS("http://www.w3.org/2000/svg", "text");\n    labelEl.setAttribute("x", xScale(i) + (width / data.labels.length) / 2);\n    labelEl.setAttribute("y", height + 15);\n    labelEl.setAttribute("text-anchor", "middle");\n    labelEl.setAttribute("fill", "#333");\n    labelEl.textContent = label;\n    g.appendChild(labelEl);\n  });\n  \n  // Add y-axis line\n  const yAxis = document.createElementNS("http://www.w3.org/2000/svg", "line");\n  yAxis.setAttribute("x1", 0);\n  yAxis.setAttribute("y1", 0);\n  yAxis.setAttribute("x2", 0);\n  yAxis.setAttribute("y2", height);\n  yAxis.setAttribute("stroke", "#333");\n  g.appendChild(yAxis);\n  \n  // Add x-axis line\n  const xAxis = document.createElementNS("http://www.w3.org/2000/svg", "line");\n  xAxis.setAttribute("x1", 0);\n  xAxis.setAttribute("y1", height);\n  xAxis.setAttribute("x2", width);\n  xAxis.setAttribute("y2", height);\n  xAxis.setAttribute("stroke", "#333");\n  g.appendChild(xAxis);\n</script>	{"asa_data": {"view": "stats", "groups": [{"field": "patient.asa_status", "label": "ASA"}], "dataset": "innovian_cases", "measures": [{"agg": "count_cases", "field": "", "label": "Cases"}]}}	1791533603696	1791533603696	1791776144932	f
