 margin.top - margin.bottom;\n  \n  // Create chart area\n  const g = document.createElementNS("http://www.w3.org/2000/svg", "g");\n  g.setAttribute("transform", `translate(${margin.left},${margin.top})`);\n  svg.appendChild(g);\n  \n  // Scales\n  const xScale = (i) => i * (width / data.labels.length);\n  const yScale = (v) => height - (v / Math.max(...data.series[0].values)) * height;\n  \n  // Draw bars\n  data.labels.forEach((label, i) => {\n    const value = data.series[0].values[i];\n    const barHeight = yScale(value);\n    \n    const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");\n    rect.setAttribute("x", xScale(i));\n    rect.setAttribute("y", height - barHeight);\n    rect.setAttribute("width", width / data.labels.length - 10);\n    rect.setAttribute("height", barHeight);\n    rect.setAttribute("fill", colors[label] || "#666");\n    g.appendChild(rect);\n    \n    // Add value label on top of bar\n    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");\n    text.setAttribute("x", xScale(i) + (width / data.labels.length) / 2);\n    text.setAttribute("y", height - barHeight - 5);\n    text.setAttribute("text-anchor", "middle");\n    text.setAttribute("fill", "#333");\n    text.textContent = value;\n    g.appendChild(text);\n    \n    // Add category label below x-axis\n    const labelEl = document.createElementNS("http://www.w3.org/2000/svg", "text");\n    labelEl.setAttribute("x", xScale(i) + (width / data.labels.length) / 2);\n    labelEl.setAttribute("y", height + 15);\n    labelEl.setAttribute("text-anchor", "middle");\n    labelEl.setAttribute("fill", "#333");\n    labelEl.textContent = label;\n    g.appendChild(labelEl);\n  });\n  \n  // Add y-axis line\n  const yAxis = document.createElementNS("http://www.w3.org/2000/svg", "line");\n  yAxis.setAttribute("x1", 0);\n  yAxis.setAttribute("y1", 0);\n  yAxis.setAttribute("x2", 0);\n  yAxis.setAttribute("y2", height);\n  yAxis.setAttribute("stroke", "#333"