   // Create blob and download link\n    const blob = new Blob([svgString], {type: 'image/svg+xml;charset=utf-8'});\n    const url = URL.createObjectURL(blob);\n    \n    // Create a temporary canvas to convert SVG to PNG\n    const img = new Image();\n    img.onload = function() {\n      const canvas = document.createElement('canvas');\n      canvas.width = img.width;\n      canvas.height = img.height;\n      const ctx = canvas.getContext('2d');\n      ctx.drawImage(img, 0, 0);\n      \n      // Convert to PNG and download\n      const pngUrl = canvas.toDataURL('image/png');\n      const a = document.createElement('a');\n      a.href = pngUrl;\n      a.download = 'asa_status_distribution.png';\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      \n      // Cleanup\n      URL.revokeObjectURL(url);\n    };\n    \n    img.src = url;\n  }\n</script>\n</view>\n</artifact>	[{"data": {"asa_data": {"view": "stats", "groups": [{"field": "patient.asa_status", "label": "ASA"}], "dataset": "innovian_cases", "measures": [{"agg": "count_cases", "field": "", "label": "Cases"}]}}, "html": "<style>\\n  #chart-container {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    gap: 15px;\\n    padding: 20px;\\n  }\\n  #chart {\\n    max-width: 500px;\\n    width: 100%;\\n  }\\n  .download-btn {\\n    padding: 10px 20px;\\n    background-color: var(--accent, #007bff);\\n    color: white;\\n    border: none;\\n    border-radius: 4px;\\n    cursor: pointer;\\n    font-size: 14px;\\n    display: flex;\\n    align-items: center;\\n    gap: 8px;\\n  }\\n  .download-btn:hover {\\n    opacity: 0.9;\\n  }\\n  .download-icon {\\n    width: 16px;\\n    height: 16px;\\n    fill: currentColor;\\n  }\\n</style>\\n\\n<div id=\\"chart-container\\">\\n  <div id=\\"chart\\"></div>\\n  <button class=\\"download-btn\\" onclick=\\"downloadChart()\\">\\n    <svg class=\\"download-icon\\" viewBox=\\"0 0 24 24\\">\\n      <path d=\\"