, "label": "Attending intensivist", "max_length": 200}, {"id": "code_status", "type": "radio", "label": "Code status", "indexed": true, "options": [{"label": "Full code", "value": "full"}, {"label": "DNR", "value": "dnr"}, {"label": "Limited treatment", "value": "limited"}, {"label": "Palliative", "value": "palliative"}], "option_columns": 4}]}, {"id": "background", "title": "History · ประวัติ", "fields": [{"id": "sex", "type": "radio", "label": "Sex", "options": [{"label": "Male", "value": "male"}, {"label": "Female", "value": "female"}], "option_columns": 2}, {"id": "weight_kg", "max": 400, "min": 1, "type": "decimal", "unit": "kg", "label": "Weight", "decimals": 1}, {"id": "height_cm", "max": 250, "min": 40, "type": "number", "unit": "cm", "label": "Height"}, {"id": "bmi", "type": "calculated", "unit": "kg/m²", "label": "BMI", "formula": "weight_kg / ((height_cm / 100) ^ 2)", "decimals": 1}, {"id": "pbw_kg", "type": "calculated", "unit": "kg", "label": "Predicted body weight", "formula": "IF(sex='male', 50, IF(sex='female', 45.5, NULL)) + 0.91 * (height_cm - 152.4)", "decimals": 1, "description": "For lung-protective ventilation (6–8 mL/kg PBW)"}, {"id": "comorbid", "type": "multiselect", "label": "Comorbidities", "options": [{"label": "Hypertension", "value": "htn"}, {"label": "Diabetes", "value": "dm"}, {"label": "Coronary disease", "value": "cad"}, {"label": "Heart failure", "value": "chf"}, {"label": "CKD", "value": "ckd"}, {"label": "ESRD on dialysis", "value": "esrd"}, {"label": "COPD / asthma", "value": "copd"}, {"label": "Cirrhosis", "value": "cirrhosis"}, {"label": "Previous stroke", "value": "stroke"}, {"label": "Malignancy", "value": "malignancy"}, {"label": "Immunosuppressed", "value": "immuno"}], "option_columns": 3}, {"id": "allergies", "type": "textarea", "label": "Allergies", "max_length": 1000}, {"id": "home_meds", "type": "textarea", "label": "Home medications (anticoagulants / antiplatelets first)", "max_length": 2000}]}, {"id": "initial", "title": "Initial status · สภาวะแรกรับ", "fields": [{"id": "airway", "type": "radio", "label": "Airway", "options": [{"label": "Natural", "value": "natural"}, {"label": "Endotracheal tube", "value": "ett"}, {"label": "Tracheostomy", "value": "trach"}, {"label": "NIV / HFNC", "value": "niv"}], "option_columns": 4}, {"id": "gcs_admit", "max": 15, "min": 3, "type": "integer", "label": "GCS on admission"}, {"id": "map_admit", "max": 250, "min": 0, "type": "number", "unit": "mmHg", "label": "MAP"}, {"id": "vasopressor_admit", "type": "checkbox", "label": "On vasopressor"}, {"id": "lactate_admit", "max": 30, "min": 0, "type": "decimal", "unit": "mmol/L", "label": "Lactate", "decimals": 1}, {"id": "apache_ii", "max": 71, "min": 0, "type": "integer", "label": "APACHE II (first 24 h)", "indexed": true}, {"id": "sofa_admit", "max": 24, "min": 0, "type": "integer", "label": "SOFA on admission", "indexed": true}], "layout": {"type": "grid", "columns": 2}}, {"id": "goals", "title": "Goals of care · เป้าหมายการรักษา", "fields": [{"id": "family_informed", "type": "checkbox", "label": "Family informed of ICU admission"}, {"id": "goals_of_care", "type": "textarea", "label": "Goals of care / family meeting notes", "max_length": 2000}, {"id": "assessed_by", "type": "text", "label": "Assessed by", "required": true, "max_length": 200}, {"id": "assessor_sign", "type": "signature", "label": "Signature"}]}], "style_id": "form.a4.medical", "description": "แบบประเมินแรกรับผู้ป่วย ICU – used by every ICU workflow", "schema_version": 1}	cd2414bea668f091e28eb88d0fbfb361c7d68c013e5550f05627c68f9f4731e4	1791867833585	claude-import	\N	\N
neuro_icu_assessment	1	draft	{"paper": {"size": "A4", "footer": {"left": "{title}", "right": "{page}/{pages}"}, "orientation": "portrait"}, "title": "Neuro ICU Assessment", "format": "flora.form/1", "font_id": "noto-sans-thai", "form_id": "neuro_icu_assessment", "offline": true, "sections": [{"id": "diagnosis", "title": "Neurological diagnosis · การวินิจฉัย", "fields": [{"id": "neuro_dx", "type": "radio", "label": "Primary neurological diagnosis", "indexed": true, "options": [{"label": "Traumatic brain injury", "value": "tbi"}, {"label": "Subarachnoid haemorrhage", "value": "sah"}, {"label": "Intracerebral haemorrhage", "value": "ich"}, {"label": "Acute ischaemic stroke", "value": "stroke"}, {"label": "Post-craniotomy / tumour", "value": "post_crani"}, {"label": "Status epilepticus", "value": "status"}, {"label": "CNS infection", "value": "cns_inf"}, {"label": "Spinal cord injury", "value": "sci"}, {"label": "Other", "value": "other"}], "required": true, "option_columns": 3}, {"id": "ictus_at", "type": "datetime", "label": "Onset / injury time"}, {"id": "neurosurgeon", "type": "text", "label": "Neurosurgeon / neurologist", "max_length": 200}]}, {"id": "baseline", "title": "Baseline neuro exam · ตรวจร่างกายแรกรับ", "fields": [{"id": "gcs_e", "type": "radio", "label": "Eye opening (E)", "options": [{"label": "4 – Spontaneous", "value": "4"}, {"label": "3 – To voice", "value": "3"}, {"label": "2 – To pain", "value": "2"}, {"label": "1 – None", "value": "1"}], "option_columns": 4}, {"id": "gcs_v", "type": "radio", "label": "Verbal (V)", "options": [{"label": "5 – Oriented", "value": "5"}, {"label": "4 – Confused", "value": "4"}, {"label": "3 – Words", "value": "3"}, {"label": "2 – Sounds", "value": "2"}, {"label": "1 – None", "value": "1"}, {"label": "T – Intubated", "value": "t"}], "option_columns": 3}, {"id": "gcs_m", "type": "radio", "label": "Motor (M)", "options": [{"label": "6 – Obeys", "value": "6"}, {"label": "5 – Localises", "value": "5"}, {"label": "4 – Withdraws", "value": "4"}, {"label": "3 – Abnormal flexion", "value": "3"}, {"label": "2 – Extension", "value": "2"}, {"label": "1 – None", "value": "1"}], "option_columns": 3}, {"id": "gcs_total", "type": "calculated", "label": "GCS total", "formula": "IF(gcs_e='4', 4, IF(gcs_e='3', 3, IF(gcs_e='2', 2, IF(gcs_e='1', 1, NULL)))) + IF(gcs_v='5', 5, IF(gcs_v='4', 4, IF(gcs_v='3', 3, IF(gcs_v='2', 2, IF(gcs_v='1', 1, IF(gcs_v='t', 1, NULL)))))) + IF(gcs_m='6', 6, IF(gcs_m='5', 5, IF(gcs_m='4', 4, IF(gcs_m='3', 3, IF(gcs_m='2', 2, IF(gcs_m='1', 1, NULL))))))", "indexed": true, "decimals": 0}, {"id": "pupil_l_mm", "max": 9, "min": 1, "type": "decimal", "unit": "mm", "label": "Left pupil size", "decimals": 1}, {"id": "pupil_l_react", "type": "select", "label": "Left pupil reaction", "options": [{"label": "Brisk", "value": "brisk"}, {"label": "Sluggish", "value": "sluggish"}, {"label": "Fixed", "value": "fixed"}, {"label": "Closed / unable", "value": "closed"}]}, {"id": "pupil_r_mm", "max": 9, "min": 1, "type": "decimal", "unit": "mm", "label": "Right pupil size", "decimals": 1}, {"id": "pupil_r_react", "type": "select", "label": "Right pupil reaction", "options": [{"label": "Brisk", "value": "brisk"}, {"label": "Sluggish", "value": "sluggish"}, {"label": "Fixed", "value": "fixed"}, {"label": "Closed / unable", "value": "closed"}]}, {"id": "motor_power", "cell": {"max": 5, "min": 0, "type": "integer"}, "cols": [{"id": "prox", "label": "Proximal"}, {"id": "dist", "label": "Distal"}], "rows": [{"id": "rue", "label": "Right arm"}, {"id": "lue", "label": "Left arm"}, {"id": "rle", "label": "Right leg"}, {"id": "lle", "label": "Left leg"}], "type": "matrix", "label": "Motor power (MRC 0–5)"}, {"id": "brainstem", "type": "multiselect", "label": "Brainstem reflexes present", "options": [{"label": "Corneal", "value": "corneal"}, {"label": "Cough", "value": "cough"}, {"label": "Gag", "value": "gag"}, {"label": "Oculocephalic", "value": "oculo"}], "option_columns": 4}]}, {"id": "tbi", "title": "TBI", "fields": [{"id": "tbi_severity", "type": "radio", "label": "Severity (by GCS)", "options": [{"label": "Mild 13–15", "value": "mild"}, {"label": "Moderate 9–12", "value": "moderate"}, {"label": "Severe 3–8", "value": "severe"}], "option_columns": 3}, {"id": "marshall_ct", "max": 6, "min": 1, "type": "integer", "label": "Marshall CT class"}, {"id": "polytrauma", "type": "checkbox", "label": "Polytrauma"}], "visibility": {"when": {"field": "neuro_dx", "value": "tbi", "operator": "equals"}}}, {"id": "sah", "title": "Subarachnoid haemorrhage", "fields": [{"id": "hunt_hess", "type": "radio", "label": "Hunt & Hess", "indexed": true, "options": [{"label": "I", "value": "1"}, {"label": "II", "value": "2"}, {"label": "III", "value": "3"}, {"label": "IV", "value": "4"}, {"label": "V", "value": "5"}], "option_columns": 5}, {"id": "wfns", "type": "radio", "label": "WFNS grade", "options": [{"label": "I", "value": "1"}, {"label": "II", "value": "2"}, {"label": "III", "value": "3"}, {"label": "IV", "value": "4"}, {"label": "V", "value": "5"}], "option_columns": 5}, {"id": "mfisher", "type": "radio", "label": "Modified Fisher", "options": [{"label": "0", "value": "0"}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "3", "value": "3"}, {"label": "4", "value": "4"}], "option_columns": 5}, {"id": "aneurysm_tx", "type": "radio", "label": "Aneurysm treatment", "options": [{"label": "Coiling", "value": "coil"}, {"label": "Clipping", "value": "clip"}, {"label": "Pending", "value": "pending"}, {"label": "Not treated", "value": "none"}], "option_columns": 4}, {"id": "nimodipine", "type": "checkbox", "label": "Nimodipine started"}], "visibility": {"when": {"field": "neuro_dx", "value": "sah", "operator": "equals"}}}, {"id": "ich", "title": "Intracerebral haemorrhage – ICH score", "fields": [{"id": "ich_volume_ml", "max": 300, "min": 0, "type": "integer", "unit": "mL", "label": "Haematoma volume (ABC/2)"}, {"id": "ich_ivh", "type": "checkbox", "label": "In