sah", "operator": "equals"}]}}}, {"id": "icp", "title": "ICP monitoring and targets · เป้าหมาย ICP/CPP", "fields": [{"id": "icp_device", "type": "radio", "label": "ICP device", "options": [{"label": "None", "value": "none"}, {"label": "EVD", "value": "evd"}, {"label": "Parenchymal bolt", "value": "parenchymal"}], "option_columns": 3}, {"id": "evd_level", "max": 30, "min": 0, "type": "integer", "unit": "cmH₂O", "label": "EVD level above tragus", "visibility": {"when": {"field": "icp_device", "value": "evd", "operator": "equals"}}}, {"id": "icp_target", "max": 30, "min": 10, "type": "integer", "unit": "mmHg", "label": "ICP threshold"}, {"id": "cpp_target_low", "max": 90, "min": 40, "type": "integer", "unit": "mmHg", "label": "CPP target – lower"}, {"id": "cpp_target_high", "max": 110, "min": 50, "type": "integer", "unit": "mmHg", "label": "CPP target – upper"}, {"id": "assessed_by", "type": "text", "label": "Assessed by", "required": true, "max_length": 200}]}], "style_id": "form.a4.medical", "description": "แบบประเมินทางระบบประสาทแรกรับ Neuro ICU พร้อม scale ตามโรค", "schema_version": 1}	f373f51d58fe0be26b9317bbad8a78c78c5387c0bcd0ef8bdfe1ca3e343ec7ca	1791867833589	claude-import	\N	\N
